style.css:
@-moz-document domain("google.com") {
/* Fondo con imagen GTA 6 */
  body {
    background-image: url("https://www.rockstargames.com/VI/_next/image?url=%2FVI%2F_next%2Fstatic%2Fmedia%2FLeonida_Keys_01.1af17390.jpg&w=1366&q=75") !important;
    background-size: cover !important;
    background-position: center center !important;
    background-attachment: fixed !important;
    background-repeat: no-repeat !important;
  }

  /* Fondo principal transparente */
  #main, .L3eUgb {
    background: transparent !important;
  }

  /* Buscador */
  .RNNXgb, .a4bIc {
    background: rgba(255, 255, 255, 0.15) !important;
    backdrop-filter: blur(8px) !important;
    border-radius: 12px !important;
    box-shadow: none !important;
  }

  input {
    background: transparent !important;
    color: white !important;
    border: none !important;
  }

  /* Estilo limpio para resultados */
  .MjjYud, .tF2Cxc, .g, .rc, .IsZvec, .VwiC3b, .xpdopen {
    background: rgba(255, 255, 255, 0.1) !important;
    backdrop-filter: blur(8px) !important;
    border-radius: 16px !important;
    box-shadow: none !important;
    border: none !important;
    color: white !important;
    padding: 12px !important;
    margin-bottom: 12px !important;
  }

  /* Textos blancos o celeste suave */
  .LC20lb, .DKV0Md, .VwiC3b, .TbwUpd, .NJo7tc {
    color: #ffffff !important;
  }

  a:link, a:visited {
    color: #aad2ff !important;
  }

  /* Tarjetas de imágenes */
  .c2xzTb {
    background: rgba(255, 255, 255, 0.1) !important;
    backdrop-filter: blur(6px) !important;
    border-radius: 12px !important;
    box-shadow: none !important;
  }

  /* Botón "mostrar más imágenes" */
  .VuuXrf {
    background: rgba(255, 255, 255, 0.1) !important;
    color: white !important;
    backdrop-filter: blur(4px) !important;
    border-radius: 8px !important;
    border: none !important;
  }

  /* Quitar el footer feo */
  #fbar {
    display: none !important;
  }

  /* Quitar líneas o bordes oscuros */
  *, *::before, *::after {
    box-shadow: none !important;
    border: none !important;
  }

  /* Ajustes para menú superior */
  .hdtb-mitem, .hdtb-mitem a {
    color: #ffffffcc !important;
  }
}
